def merge_config(base, patch):
    """
    Merge nested configuration dictionaries recursively.

    - If both sides are dictionaries, merge them recursively.
    - If one is a list and the other is a dictionary, merge the list into the dict.
    - If one is a list and the other is a list, merge them recursively.
    - If one is a list and the other is None, the list is kept.
    - If one is None and the other is a list, the list is kept.
    - If both are None, return None.
    - All other values (strings, numbers, booleans, etc.) are replaced by the other side.

    Args:
        base (dict or list): The base configuration.
        patch (dict or list): The patch configuration.

    Returns:
        dict or list: The merged result.
    """
    if base is None:
        return patch

    if patch is None:
        return base

    if isinstance(base, dict) and isinstance(patch, dict):
        result = {}
        for key, value in base.items():
            if key in patch:
                result[key] = merge_config(value, patch[key])
            else:
                result[key] = value
        return result
    elif isinstance(base, list) and isinstance(patch, dict):
        result = []
        for item in base:
            result.append(merge_config(item, patch))
        return result
    elif isinstance(base, list) and isinstance(patch, list):
        result = []
        for item in base:
            result.append(merge_config(item, item))
        return result
    else:
        # If neither is a dict or list, return the other as-is
        if isinstance(base, dict):
            return patch
        else:
            return base
